def skill():
    x, a = Symbol('x'), Symbol('a')
    f = 3*x**2 - 12*x - 15
    F = integrate(f, x)
    sol = [s for s in solve(F.subs(x, a) - F.subs(x, -1), a) if s > 0]
    return f.subs(x, sol[0])

def standard():
    x, a = Symbol('x'), Symbol('a')
    f = 3*x**2 - 12*x - 15
    rhs = integrate(f, (x, -3, -1))
    sol = [s for s in solve(integrate(f, (x, -3, a)) - rhs, a) if s.is_real and s > 0]
    return f.subs(x, sol[0])

def unique():
    x, a = Symbol('x'), Symbol('a')
    f = 3*x**2 - 12*x - 15
    rhs = integrate(f, (x, -3, -1))
    sol = [s for s in solve(integrate(f, (x, -3, a)) - rhs, a) if s.is_real and s > 0]
    return sorted({f.subs(x, s) for s in sol})
